import numpy as np


def q187(y, p):
    y = np.asarray(y, float)
    difference = y[:, None] - y[None, :]
    affinity = 1 / (1 + (difference * difference).sum(-1))
    np.fill_diagonal(affinity, 0)
    q = affinity / affinity.sum()
    return 4 * (
        (np.asarray(p) - q)[:, :, None] * affinity[:, :, None] * difference
    ).sum(1)
